<script setup lang="ts">
const db=useSupabaseClient(),route=useRoute(),busy=ref(true),error=ref(''),rows=ref<any[]>([]),schoolName=ref('')
onMounted(async()=>{const {data:{user}}=await db.auth.getUser();if(!user){await navigateTo('/login');return}const r=await db.from('school_memberships').select('school_id,role,schools(name)').eq('user_id',user.id);if(r.error){error.value=r.error.message;busy.value=false;return}const id=typeof route.query.school==='string'?route.query.school:'';const m=(r.data||[]).find(x=>x.school_id===id&&['school_admin','teacher'].includes(x.role));if(!m){error.value='You do not have access to this school.';busy.value=false;return}schoolName.value=(m.schools as any)?.name||'School';const [o,p]=await Promise.all([db.from('competitions').select('id,name,status,school_year').eq('organiser_school_id',id).limit(500),db.from('competition_schools').select('competition_id,competitions(id,name,status,school_year)').eq('school_id',id).limit(500)]);if(o.error||p.error){error.value=(o.error||p.error)!.message;busy.value=false;return}const map=new Map<string,any>();for(const c of o.data||[])map.set(c.id,c);for(const x of p.data||[]){const c:any=x.competitions;if(c&&!Array.isArray(c))map.set(c.id,c)}rows.value=[...map.values()];busy.value=false})
</script>
<template><div class="page"><div class="shell admin-section"><NuxtLink to="/school/dashboard">← School Dashboard</NuxtLink><h1>{{schoolName}} — Competitions</h1><p class="notice">Read-only list of competitions organised by or involving this school.</p><p v-if="busy">Loading…</p><p v-if="error" class="error" role="alert">{{error}}</p><div v-if="!busy&&!error" class="card"><h2>Competitions ({{rows.length}})</h2><div v-for="c in rows" :key="c.id" class="data-row"><span>{{c.name}}</span><small>{{c.school_year}} · {{c.status}}</small></div><p v-if="!rows.length">No competitions found.</p></div></div></div></template>
